// Contracts v1 (frozen 2026-10-10): project records, preferences, tutor targets.
// Consumers: apps/web/lib/storage (backend), apps/web/lib/targets + components/tutor (interaction),
// apps/web/app (frontend). Changes after the freeze go through the lead and bump CONTRACTS_VERSION.
import type { LabMode, LabType } from "./common";

export const CONTRACTS_VERSION = 1;

// ---------- Projects ----------

/** JSON-serializable lab state. Each lab defines its own shape and bumps `dataVersion` when it changes. */
export interface ProjectRecord<T = unknown> {
  /** UUID generated by the store. */
  id: string;
  /** `null` for a guest project kept on this device. */
  ownerId: string | null;
  lab: LabType;
  mode: LabMode;
  /** Typed by the learner; shown as-is in both languages. */
  title: string;
  data: T;
  dataVersion: number;
  /** Starts at 1 and increases by exactly 1 on every successful update or restore. */
  revision: number;
  /** ISO 8601 UTC. */
  createdAt: string;
  updatedAt: string;
}

export type ProjectSummary = Omit<ProjectRecord, "data">;

export interface ProjectSnapshot<T = unknown> {
  id: string;
  projectId: string;
  /** Revision of the project when the snapshot was taken. */
  revision: number;
  label: string;
  data: T;
  dataVersion: number;
  createdAt: string;
}

export type ProjectSnapshotSummary = Omit<ProjectSnapshot, "data">;

export interface CreateProjectInput<T = unknown> {
  lab: LabType;
  mode: LabMode;
  title: string;
  data: T;
  dataVersion: number;
}

export interface UpdateProjectInput<T = unknown> {
  /** The revision the caller last read. A mismatch fails with `revision_conflict` and writes nothing. */
  expectedRevision: number;
  title?: string;
  mode?: LabMode;
  data?: T;
  dataVersion?: number;
}

export type ProjectStoreErrorCode =
  | "not_found"
  | "revision_conflict"
  /** A stored record failed validation. The record is left in place, never silently deleted. */
  | "corrupt"
  /** Storage cannot be opened (private mode, blocked, quota, server unreachable). */
  | "unavailable"
  | "invalid_input";

export class ProjectStoreError extends Error {
  readonly code: ProjectStoreErrorCode;
  constructor(code: ProjectStoreErrorCode, message?: string) {
    super(message ?? code);
    this.name = "ProjectStoreError";
    this.code = code;
  }
}

export interface ProjectListResult {
  projects: ProjectSummary[];
  /** IDs of records that exist but could not be read. The UI reports them instead of hiding them. */
  corruptIds: string[];
}

/** Implemented by the guest IndexedDB store now and by the account API later. All failures throw ProjectStoreError. */
export interface ProjectStore {
  list(filter?: { lab?: LabType }): Promise<ProjectListResult>;
  get<T = unknown>(id: string): Promise<ProjectRecord<T>>;
  create<T = unknown>(input: CreateProjectInput<T>): Promise<ProjectRecord<T>>;
  update<T = unknown>(id: string, input: UpdateProjectInput<T>): Promise<ProjectRecord<T>>;
  /** Removes the project and its snapshots. */
  remove(id: string): Promise<void>;
  createSnapshot(projectId: string, label: string): Promise<ProjectSnapshotSummary>;
  listSnapshots(projectId: string): Promise<ProjectSnapshotSummary[]>;
  /** Reads one snapshot with its data, without restoring it (added 2026-10-15, additive). */
  getSnapshot<T = unknown>(projectId: string, snapshotId: string): Promise<ProjectSnapshot<T>>;
  /** Copies the snapshot's data into the project as a new revision. The snapshot itself is kept. */
  restoreSnapshot<T = unknown>(projectId: string, snapshotId: string, expectedRevision: number): Promise<ProjectRecord<T>>;
}

// ---------- Preferences ----------

export type AvatarStyle = "none" | "boy" | "man" | "girl" | "woman";

export interface Preferences {
  version: 1;
  /** `system` follows the operating-system setting. */
  reducedMotion: "system" | "on" | "off";
  /** Audio is muted until the learner turns it on. */
  soundEnabled: boolean;
  avatar: AvatarStyle;
  /** When false the robot is not rendered; text help stays available. */
  robotVisible: boolean;
  /** 30 is the stable performance option; movement durations are identical. */
  robotFrameRate: 60 | 30;
  /** The learner chose to skip the workstation scene. */
  skipWorkstation: boolean;
}

export const DEFAULT_PREFERENCES: Preferences = {
  version: 1,
  reducedMotion: "system",
  soundEnabled: false,
  avatar: "none",
  robotVisible: true,
  robotFrameRate: 60,
  skipWorkstation: false,
};

export interface PreferencesStore {
  /** Never throws: returns DEFAULT_PREFERENCES when nothing is stored or the stored value is unreadable. */
  load(): Promise<Preferences>;
  /** Merges the patch, persists and returns the result. Throws ProjectStoreError("unavailable") if it cannot persist. */
  save(patch: Partial<Omit<Preferences, "version">>): Promise<Preferences>;
}

// ---------- Tutor targets ----------

export type TutorTargetKind =
  | "ui"
  | "component"
  | "connector"
  | "port"
  | "cable-end"
  | "setting";

/**
 * Stable semantic ID: `<scope>:<kind>:<name>`, lower case, e.g. `shell:ui:nav-pc`,
 * `pc:port:mb-atx24`, `network:component:router-1`. Never a CSS selector.
 */
export type TargetId = string;

export const TARGET_ID_PATTERN = /^[a-z][a-z0-9-]*:[a-z][a-z-]*:[A-Za-z0-9._#/-]+$/;

export interface TutorTargetRef {
  id: TargetId;
  kind: TutorTargetKind;
  /** Guidance is stale when these no longer match the active project. */
  projectRevision?: number;
  executionId?: string;
}

/** Viewport rectangle in CSS pixels, as returned by getBoundingClientRect. */
export interface TargetRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export type TargetResolution =
  | { status: "visible"; rect: TargetRect }
  /** Registered and laid out, but outside the viewport; `reveal` can scroll it into view. */
  | { status: "offscreen"; rect: TargetRect }
  /** Registered but not rendered (collapsed panel, display none, zero size). */
  | { status: "hidden" }
  /** Not registered in the current state. The tutor must not point at it. */
  | { status: "unknown" };
